<script>
import axios from "../../axios_instance";
import { Form } from "vform";
export default {
    props: {
    },
    components: {
        // VueRecaptcha, facebookLogin 
    },
    data() {
        return {
            base_url: window.base_url,
            api_url: window.api_url,
            DepartmentsItems: [],
            token: this.$localStorage.get("d_token"),
            addForm: new Form({
                tasks: [],
                quarter: 2,

            }),
            roles: [],
        };
    },
    created() { 
        this.getItems();
    },
    methods: {
         

        async getItems() { 
             let loader = this.$loading.show();
            try {
                await axios
                    .get(this.api_url + "priority_tasks/"+this.$route.params.id, {
                        headers: {
                            "Content-Type": "application/json",
                            Authorization: this.token ? `Bearer ${this.token}` : ""
                        },
                    })
                    .then(({
                        data
                    }) => {
                        this.addForm.tasks = data.data.tasks;
                        this.addForm.quarter = data.data.quarter ;
                        loader.hide();
                    });
            } catch (error) {
                loader.hide();
            }
        },
        async update(){
            try {
                let loader = this.$loading.show();
                this.addForm.post(this.api_url + "priority_task_items_update?id=" + this.$route.params.id, {
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: this.token ? `Bearer ${this.token}` : ""
                    },
                }).then((res) => {
                    console.log(res);
                    if (res.data.success) {
                        this.$toasted.show(res.data.message, {
                            theme: "bubble",
                            duration: 5000,
                            position: "bottom-right",
                        });
                    }
                    loader.hide();
                    //  this.$router.push('/users');
                }, (error) => {
                    console.log(error);
                    loader.hide();
                })
            } catch (error) {
                // loader.hide(); 
                console.log(error);
            }
        }


    },
    computed: {},
};
</script>
