<template>
  <div>
    <div class="app-content content">
      <div class="content-wrapper">
        <div class="content-header row">
          <div class="content-header-left col-12 mb-1 mt-0">
            <div class="row breadcrumbs-top">
              <div class="col-sm-9">
                <div class="breadcrumb-wrapper col-9">
                  <ol class="breadcrumb p-0 mb-0">
                    <li class="breadcrumb-item">
                      <router-link :to="{ path: '/' }"><i class="bx bx-home-alt"></i></router-link>
                    </li>
                    <li class="breadcrumb-item active"> Priority Tasks
                    </li>
                  </ol>
                </div>
              </div>
              <div class=" col-sm-3">
                <router-link class="btn btn-primary add-btn" :to="{ path: '/priority_task_add' }"><i
                    class="bx bx-add-alt"></i>
                  New Tasks
                </router-link>
              </div>

            </div>
          </div>
        </div>
        <div class="content-body">
          <div class="users-list-filter px-1">
          </div>

          <section id="basic-datatable">
            <div class="row">
              <div class="col-12">
                <div class="card">
                  <div class="card-content">
                    <div class="card-body card-dashboard">

                      <div class="table-responsive">
                        <h4>Tasks </h4><br>
                        <br>
                      </div>
                      <div class="row">
                        <div class="col-md-3">

                          <div class="form-group">
                            <label for="Profession">Quarter </label>
                            <div class="controls">
                              <select class="form-control" v-on:change="getItems()" v-model="filterForm.quarter"
                                id="users-list-verified">
                                <option value="">Select One</option>
                                <option v-for="row in quarter_months" :key="row.id" :value="row.id">
                                  {{ row.name }}
                                </option>
                              </select>
                            </div>
                          </div>

                        </div>
                      </div>
                      <table class="table table-bordered table-sm">
                        <thead class="thead-dark">

                          <tr>
                            <th>Priority</th>
                            <th>Major Task </th>
                            <th style="">Qtr-2 (%)</th>
                            <template v-if="filterForm.quarter == 3">
                              <th style="">January (%)</th>
                              <th style="">February (%)</th>
                              <th style="">March (%)</th>
                            </template>
                            <template v-if="filterForm.quarter == 4">
                              <th style="">April (%)</th>
                              <th style="">May (%)</th>
                              <th style="">June (%)</th>
                            </template>
                            <template v-if="filterForm.quarter == 1">
                              <th style="">July (%)</th>
                              <th style="">August (%)</th>
                              <th style="">September (%)</th>
                            </template>
                            <template v-if="filterForm.quarter == 2">
                              <th style="">October (%)</th>
                              <th style="">November (%)</th>
                              <th style="">December (%)</th>
                            </template>
                            <th style="">Achievement (%)</th>
                            <th style="">Action</th>
                          </tr>

                        </thead>
                        <tbody>
                          <template v-for="(quarters, index) in items">
                            <tr class="text-center" :key="index">
                              <th colspan="7">Priority (Quarter -{{ quarters.quarter_id }})</th>
                            </tr>
                            <template v-for="(item, index2) in quarters.tasks">
                              <tr class="text-center" :key="index2">
                                <td>Priority {{ index2 + 1 }}</td>
                                <td style="text-align: left;">{{ item.task }}</td>
                                <template v-if="filterForm.quarter == 3">
                                  <td>{{ item.jan }}</td>
                                  <td>{{ item.feb }}</td>
                                  <td>{{ item.mar }}</td>
                                </template>
                                <template v-if="filterForm.quarter == 4">
                                  <td>{{ item.apr }}</td>
                                  <td>{{ item.may }}</td>
                                  <td>{{ item.jun }}</td>
                                </template>
                                <template v-if="filterForm.quarter == 1">
                                  <td>{{ item.jul }}</td>
                                  <td>{{ item.aug }}</td>
                                  <td>{{ item.sep }}</td>
                                </template>
                                <template v-if="filterForm.quarter == 2">
                                  <td>{{ item.oct }}</td>
                                  <td>{{ item.nov }}</td>
                                  <td>{{ item.dec }}</td>
                                </template>

                                <td>{{ item.quarter_weightage }}</td>
                                <td>
                                  <div class="progress-container">
                                    <div class="progress-bar" :style="{ width: item.quarter_achiv + '%' }"></div>
                                    <span class="percentage-label">{{ item.quarter_achiv }}%</span>
                                  </div>
                                </td>
                                <td v-if="index2 == 0" :rowspan="quarters.tasks.length">
                                  <router-link :to="{ path: '/priority_task_edit/' + quarters.id }"><i
                                      class="bx bx-edit-alt"></i>Edit</router-link> | 

                                  <a @click="delete_row(quarters.id )" class="delete-icon"><i class="fas fa-trash"></i>Delete</a>
                                </td>
                              </tr>
                            </template>
                          </template>
                        </tbody>

                      </table>

                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import axios from "../../axios_instance";
import { Form } from "vform";
export default {
  props: {},
  components: {
    // VueRecaptcha, facebookLogin
  },
  data() {
    return {
      deptItems: [],
      items: [],
      token: this.$localStorage.get("d_token"),
      user_data: JSON.parse(this.$localStorage.get("user")),
      base_url: window.base_url,
      api_url: window.api_url, 
      filterForm: new Form({
        dept_id: this.$route.query.dept_id ? this.$route.query.dept_id : "",
        user_id: "",
        limit: "50",
        quarter: 2,
        year:  this.year,
      }),

    };
  },
  created() {
    this.role_id = this.user_data.role_id;
    this.getItems(); 
  },
  methods: {
    async getItems() {
      let where = '?1=1';
      if (this.filterForm.quarter) {
        where += '&quarter=' + this.filterForm.quarter;
      }

      if (this.filterForm.dept_id) {
        where += '&dept_id=' + this.filterForm.dept_id;
      }

      where += "&year=" + this.year ;

      if (this.filterForm.user_id) {
        where += '&wing_id=' + this.filterForm.user_id;
      }
      let loader = this.$loading.show();
      try {
        await axios
          .get(this.api_url + "priority_tasks" + where, {
            headers: {
              "Content-Type": "application/json",
              Authorization: this.token ? `Bearer ${this.token}` : ""
            },
          })
          .then(({
            data
          }) => {
            this.items = data.data;
            loader.hide();
          });
      } catch (error) {
        loader.hide();
      }
    },
    async delete_row(id) {
      // console.log(id);
      let loader = this.$loading.show();
      try {
        await axios
          .delete(this.api_url + "priority_tasks/" + id, {
            headers: {
              "Content-Type": "application/json",
              Authorization: this.token ? `Bearer ${this.token}` : ""
            },
          })
          .then(({
            res
          }) => {
            if (res.data.success) {
              this.$toasted.show(res.data.message, {
                theme: "bubble",
                duration: 5000,
                position: "bottom-right",
              });
            }
            this.getItems();
            loader.hide();
          });
      } catch (error) {
        loader.hide();
      }
    },

  },
  computed: {

  },
}
  ;
</script>
<style>
/* styles.css */
.progress-container {
  height: 30px;
  position: relative;
  background-color: #A8A6A6;
  border-radius: 50px;
  box-shadow: 2px 2px 2px #4CAF4FBB;
  /* Replace 'your-shadow-color' with the desired shadow color */
}

.progress-bar {
  height: 100%;
  width: 0;
  background: linear-gradient(to bottom, #4CAF50, #4CAF4F70, #4CAF50);
  /* Gradient from green to blue to green, top to bottom */
  position: absolute;
  transition: width 0.5s;
  border-radius: 50px;
}



.percentage-label {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: #fff;
}
</style>
